let age: number = 25;
let name: string = "Alice";
let isActive: boolean = true;
console.log(name, age, isActive);

type User = { id: string; name: string; age: number };
const format = (user: User) => `Hello ${user.name}, age ${user.age}`;
console.log(format({ id: "1", name: "Dev", age: 25 }));

interface Person {
    name: string;
    age: number;
}

const greet = (p: Person) => `Hi ${p.name}!`;
console.log(greet({ name: "Bob", age: 30 }));

function add(a: number, b: number): number {
    return a + b;
}

console.log(add(5, 3));

function identity<T>(arg: T): T {
    return arg;
}

console.log(identity<string>("hello"));
console.log(identity<number>(42));

class Box<T> {
    private value: T;
    constructor(value: T) { this.value = value; }
    getValue(): T { return this.value; }
}

const box = new Box<string>("Hello");
console.log(box.getValue());

type Status = "pending" | "success" | "error";
function handleStatus(s: Status) {
    console.log(`Status: ${s}`);
}

handleStatus("success");

enum Color {
    Red = "RED",
    Green = "GREEN",
    Blue = "BLUE"
}

console.log(Color.Red);

interface User {
    name: string;
    email?: string;
}

const user: User = { name: "Alice" };
console.log(user.email ?? "No email");

type Point = { x: number; y: number };
const dist = (a: Point, b: Point) => Math.hypot(a.x - b.x, a.y - b.y);
console.log(dist({ x: 0, y: 0 }, { x: 3, y: 4 }));

async function fetchData(): Promise<string> {
    return new Promise(resolve => {
        setTimeout(() => resolve("Data loaded"), 1000);
    });
}

fetchData().then(console.log);

interface User {
    name: string;
    age: number;
    email: string;
}

type PartialUser = Partial<User>;
const user: PartialUser = { name: "Alice" };
console.log(user);

function log(target: any, propertyKey: string) {
    console.log(`Calling ${propertyKey}`);
}

class Calculator {
    @log
    add(a: number, b: number) { return a + b; }
}

const calc = new Calculator();
calc.add(2, 3);
